function photoSVG(i){
  const pal=[["#0f3a63","#2b7bbf","#e06a24"],["#173d2e","#3fa65a","#ffd34d"],["#2a2140","#6b5bd6","#45d69b"]][i%3];
  return `<svg viewBox="0 0 1050 450" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="ph${i}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${pal[0]}"/><stop offset="1" stop-color="${pal[1]}"/></linearGradient></defs><rect width="1050" height="450" fill="url(#ph${i})"/><circle cx="880" cy="90" r="46" fill="${pal[2]}" opacity=".5"/></svg>`;
}
const TART=Object.fromEntries(["urban","carbon","wildfire","atmosphere","ocean","cryosphere","drought","airquality","ghg"].map(k=>[k,"n_"+k]));
const bgStyle=k=>`style="--bg:url(${/^data:/.test(NASA["h_"+k])?NASA["h_"+k]:new URL(NASA["h_"+k],location.href).href})"`;
