const hue = n => [...n].reduce((a,c)=>a+c.charCodeAt(0),0)%360;
const avatar = (n,cls) => PHOTO[n] ? `<img class="${cls}" src="${PHOTO[n]}" alt="${esc(n)}" loading="lazy">` : `<span class="${cls}" style="--h:${hue(n)}">${initials(n)}</span>`;

