const app = document.getElementById("app");
/* ===== Lab news = real Instagram / LinkedIn posts listed in POSTS (js/posts.js on the live site) ===== */
const IG_URL="https://www.instagram.com/iris.unist/", LI_URL="https://www.linkedin.com/company/unist-iris-lab/";
const POSTLIST=(()=>{
  const A=x=>Array.isArray(x)?x:[], man=typeof POSTS!=="undefined"?A(POSTS):[], ig=typeof IG_POSTS!=="undefined"?A(IG_POSTS):[];
  const seen=new Set(), out=[];
  [...man,...ig].forEach(p=>{ if(!p||!p.url) return; const k=p.url.split("?")[0].replace(/\/$/,""); if(seen.has(k)) return; seen.add(k); out.push({...p,src:p.src||(/linkedin\.com/.test(p.url)?"linkedin":"instagram")}); });
  return out.sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));})();
function liEmbed(u){ const m=u.match(/urn:li:(activity|share|ugcPost):(\d+)/)||u.match(/(activity|share|ugcPost)[-:](\d{10,})/); return m?`https://www.linkedin.com/embed/feed/update/urn:li:${m[1]}:${m[2]}`:null; }
function postCard(p){
  const ig=p.src==="instagram", name=ig?"Instagram":"LinkedIn", icon=ig?SOC.ig:SOC.li;
  let emb="";
  if(ig){ const u=p.url.split("?")[0]; emb=`<blockquote class="instagram-media" data-instgrm-permalink="${esc(u)}?utm_source=ig_embed" data-instgrm-version="14"><a href="${esc(u)}" target="_blank" rel="noopener">${t("news.view").replace("{s}",name)}</a></blockquote>`; }
  else { const e=liEmbed(p.url); if(e) emb=`<iframe src="${esc(e)}" title="LinkedIn post" loading="lazy" allowfullscreen></iframe>`; }
  return `<article class="post rv ${p.src}"><div class="post-h"><span class="post-ic">${icon}</span><b>${name}</b>${p.date?`<span>${esc(p.date)}</span>`:""}</div>${emb?`<div class="post-emb">${emb}</div>`:""}${p.text?`<p>${esc(p.text)}</p>`:""}<a class="more" href="${esc(p.url)}" target="_blank" rel="noopener">${t("news.view").replace("{s}",name)} ↗</a></article>`;
}
function followCards(){
  return `<div class="follow">${[[IG_URL,"Instagram","@iris.unist",SOC.ig],[LI_URL,"LinkedIn","UNIST IRIS Lab",SOC.li]].map(([u,n,h,ic])=>`<a class="follow-c rv" href="${u}" target="_blank" rel="noopener"><span class="post-ic">${ic}</span><span><b>${n}</b><small>${h}</small></span><i>↗</i></a>`).join("")}</div>`;
}
function postFeed(list){ return list.length?`<div class="posts">${list.map(postCard).join("")}</div>`:`<p class="nopost">${t("news.none")}</p>`; }
let igLoaded=false;
function loadEmbeds(){
  if(!app.querySelector(".instagram-media")) return;
  if(window.instgrm){ try{ window.instgrm.Embeds.process(); }catch(e){} return; }
  if(igLoaded) return; igLoaded=true;
  const s=document.createElement("script"); s.async=true; s.src="https://www.instagram.com/embed.js"; document.body.appendChild(s);
}
let postSrc="all";
function splitCap(p){
  const raw=String(p.text||"").replace(/\r/g,"").trim(), lines=raw.split(/\n+/).map(x=>x.trim()).filter(Boolean);
  let h=p.title||lines[0]||"", x=p.title?lines.join(" "):lines.slice(1).join(" ");
  h=h.replace(/(#[^\s#]+\s*)+$/,"").trim(); if(h.length>110){ x=h.slice(100)+" "+x; h=h.slice(0,100).replace(/\s+\S*$/,"")+"…"; }
  x=x.replace(/#[^\s#]+/g,"").replace(/\s{2,}/g," ").trim();
  return [h||(p.src==="linkedin"?"LinkedIn":"Instagram"),x];
}
const TOPICK=Object.keys(TK);
function postThumb(p,i){
  if(p.image) return `<img src="${esc(p.image)}" alt="" loading="lazy">`;
  const k=TOPICK[i%TOPICK.length]; return `<img src="${NASA[TART[k]]}" alt="" loading="lazy">`;
}
function newsCard(p,i){
  const [h,x]=splitCap(p), name=p.src==="linkedin"?"LinkedIn":"Instagram", d=p.date?String(p.date).slice(0,10).replace(/-/g,"."):"";
  return `<article class="n-card rv"><a href="${esc(p.url)}" target="_blank" rel="noopener" class="n-link"><div class="thumb">${postThumb(p,i)}<span class="src">${name}</span></div><div class="n-date">${d}</div><h3>${esc(h)}</h3>${x?`<p>${esc(x)}</p>`:""}<span class="more">${t("news.view").replace("{s}",name)} ↗</span></a></article>`;
}
