/* ================= ROUTER / WIRING ================= */
let io, carTimer;
const PAGES=["research","people","news","publications","join"];
function route(){
  let h=(location.hash||"#research").slice(1);
  if(h==="topics"||h==="apply"){ return; }
  const isTopic = h.startsWith("topic-")&&TK[h.slice(6)];
  const top = isTopic ? "research" : (PAGES.includes(h)?h:"research");
  app.innerHTML = isTopic ? viewTopic(h.slice(6)) : {research:viewResearch,people:viewPeople,news:viewNews,publications:viewPubs,join:viewJoin}[top]();
  document.querySelectorAll(".nav a").forEach(a=>a.setAttribute("aria-current", a.dataset.r===top?"page":"false"));
  document.body.dataset.page = isTopic ? "topic" : top;
  wire(h);
}
function render(){
  document.documentElement.lang = LANG==="zh"?"zh-Hans":LANG;
  document.querySelectorAll("[data-i]").forEach(el=>el.textContent=t(el.dataset.i));
  document.querySelectorAll(".lang button").forEach(b=>b.setAttribute("aria-pressed", b.dataset.lang===LANG));
  document.getElementById("foot-social").outerHTML = socialHTML("line").replace('class="social line"','class="social line" id="foot-social"');
  route();
}
function wire(h){
  clearInterval(carTimer);
  if(io) io.disconnect();
  if("IntersectionObserver" in window && !reduce){
    io=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add("in"); io.unobserve(e.target);} }),{rootMargin:"0px 0px -6% 0px"});
    app.querySelectorAll(".rv").forEach(el=>io.observe(el));
  } else app.querySelectorAll(".rv").forEach(el=>el.classList.add("in"));
  app.querySelectorAll('a[href="#topics"],a[href="#apply"]').forEach(a=>a.addEventListener("click",e=>{ e.preventDefault(); const el=document.getElementById(a.getAttribute("href").slice(1)); if(el) el.scrollIntoView({behavior:reduce?"auto":"smooth"}); else { location.hash="research"; } }));
  const sc=app.querySelector(".stage .rt");
  if(sc){
    const tabs=[...app.querySelectorAll(".tabs button")];
    const on=k=>{ sc.classList.toggle("focus",!!k); sc.querySelectorAll(".fx").forEach(z=>z.classList.toggle("live",z.dataset.fx===k)); sc.querySelectorAll(".dim,.ring").forEach(z=>z.classList.toggle("live",z.dataset.topic===k)); tabs.forEach(b=>b.classList.toggle("live",b.dataset.topic===k)); };
    const go=k=>{ location.hash="topic-"+k; };
    let touch=false; sc.addEventListener("touchstart",()=>{touch=true;},{passive:true});
    sc.querySelectorAll(".zone").forEach(z=>{ z.addEventListener("pointerenter",()=>on(z.dataset.topic)); z.addEventListener("click",()=>{ if(touch && !sc.querySelector(`.fx.live[data-fx="${z.dataset.topic}"]`)){ on(z.dataset.topic); return; } go(z.dataset.topic); }); });
    sc.addEventListener("pointerleave",()=>on(null));
    tabs.forEach(b=>{ b.addEventListener("pointerenter",()=>on(b.dataset.topic)); b.addEventListener("focus",()=>on(b.dataset.topic)); b.addEventListener("pointerleave",()=>on(null)); b.addEventListener("blur",()=>on(null)); b.addEventListener("click",()=>go(b.dataset.topic)); });
  }
  const th=app.querySelector(".t-hero .rt");
  if(th){ const k=h.slice(6); th.classList.add("focus"); th.querySelectorAll(".fx").forEach(z=>z.classList.toggle("live",z.dataset.fx===k)); th.querySelectorAll(".dim").forEach(z=>z.classList.toggle("live",z.dataset.topic===k)); }
  const car=app.querySelector("#car");
  if(car){
    const sl=[...car.querySelectorAll(".slide")], dots=[...car.querySelectorAll(".dots i")]; let i=0;
    const show=n=>{ i=(n+sl.length)%sl.length; sl.forEach((s,j)=>s.classList.toggle("on",j===i)); dots.forEach((d,j)=>d.classList.toggle("on",j===i)); car.querySelector("#car-cap").textContent=`${t("photo.cap")} · ${i+1}/${sl.length}`; };
    car.querySelector("#car-prev").onclick=()=>show(i-1); car.querySelector("#car-next").onclick=()=>show(i+1);
    if(!reduce){ carTimer=setInterval(()=>{ if(!car.matches(":hover")) show(i+1); },6000); }
  }
  app.querySelectorAll("[data-src]").forEach(b=>b.onclick=()=>{ postSrc=b.dataset.src; newsN=9; app.innerHTML=viewNews(); wire(h); });
  const nm_=app.querySelector("#news-more"); if(nm_) nm_.onclick=()=>{ const y=scrollY; newsN+=9; app.innerHTML=viewNews(); wire(h); scrollTo(0,y); };
  const q=app.querySelector("#p-q");
  if(q){
    const upd=()=>{ app.querySelector("#p-list").innerHTML=pubList(); app.querySelector("#p-stats").innerHTML=pubStats(); app.querySelectorAll("#p-years button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.y===pubY)); app.querySelectorAll("#p-topics button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.t===pubT)); };
    q.addEventListener("input",()=>{ pubQ=q.value; upd(); });
    app.querySelectorAll("#p-years button").forEach(b=>b.onclick=()=>{ pubY=b.dataset.y; upd(); });
    app.querySelectorAll("#p-topics button").forEach(b=>b.onclick=()=>{ pubT=b.dataset.t; upd(); });
  }
  app.querySelectorAll("[data-jump]").forEach(a=>a.onclick=e=>{ e.preventDefault(); const el=document.getElementById(a.dataset.jump); if(el) el.scrollIntoView({behavior:"smooth",block:"start"}); });
  app.querySelectorAll("[data-zoom]").forEach(b=>b.onclick=()=>openBox(FIG[b.dataset.zoom],b.querySelector("img").alt));
  const cp=app.querySelector("#copy-mail");
  if(cp) cp.onclick=()=>{ const done=()=>{ cp.textContent=t("copied"); setTimeout(()=>cp.textContent=t("copy"),1600); };
    const sel=()=>{ const r=document.createRange(); r.selectNodeContents(app.querySelector("#mail")); getSelection().removeAllRanges(); getSelection().addRange(r); };
    try{ navigator.clipboard.writeText("ersgis@unist.ac.kr").then(done,sel); }catch(e){ sel(); } };
}
function openBox(src,alt){
  const d=document.createElement("div"); d.className="lbox"; d.setAttribute("role","dialog"); d.setAttribute("aria-modal","true");
  d.innerHTML=`<button type="button" class="lb-x" aria-label="Close">×</button><img src="${src}" alt="${esc(alt)}">`;
  const close=()=>{ d.remove(); document.removeEventListener("keydown",kd); document.body.style.overflow=""; }; const kd=e=>{ if(e.key==="Escape") close(); };
  d.onclick=e=>{ if(e.target===d||e.target.classList.contains("lb-x")) close(); }; document.addEventListener("keydown",kd);
  document.body.appendChild(d); document.body.style.overflow="hidden"; d.querySelector(".lb-x").focus();
}
const topEl=document.getElementById("top"), burger=document.getElementById("burger");
burger.addEventListener("click",()=>{ const o=topEl.classList.toggle("open"); burger.setAttribute("aria-expanded",o); });
document.querySelectorAll(".nav a").forEach(a=>a.addEventListener("click",()=>{ topEl.classList.remove("open"); burger.setAttribute("aria-expanded","false"); }));
document.querySelectorAll(".lang button").forEach(b=>b.addEventListener("click",()=>{ LANG=b.dataset.lang; try{localStorage.setItem("iris-lang-v3",LANG);}catch(e){} render(); }));
addEventListener("hashchange",()=>{ topEl.classList.remove("open"); burger.setAttribute("aria-expanded","false"); const h=location.hash.slice(1); if(h==="topics"||h==="apply") return; route(); window.scrollTo({top:0,behavior:"instant"}); });
document.querySelectorAll("[data-emb]").forEach(el=>el.innerHTML=embSVG());
document.querySelectorAll("[data-unist]").forEach(el=>el.src=IMG.emb.unist);
document.querySelectorAll("[data-wm]").forEach(el=>el.src=NASA.wordmark);
render();

